(1, 1, 'Artificial Intelligence', '1703674196artificial-intelligence.png', '&lt;p&gt;Artificial Intelligence involves programming computers to do things that normally require human intelligence, such as seeing, hearing, talking, and making decisions.&lt;/p&gt;', 'Starts at 10 March, 2023', '1', 1, '2023-12-27 10:49:56', 1),
(2, 1, '3D printing', '1679917379printing-3d (1).png', '&lt;p&gt;Kids who want to learn about 3D printing can take this course. They&amp;rsquo;ll design and print 3D models and troubleshoot 3D printers using hands-on activities and digital tools.&lt;/p&gt;', 'Starts at 10 March, 2023', '1', 2, '2023-04-13 05:59:05', 0),
(3, 1, 'Robotics with electronics', '17036741391681329813Robotics-with-embedded.png', '&lt;p&gt;Electronics are used to design, build, and programme robots to perceive and interact with their environment.&lt;/p&gt;', 'Starts at 10 March, 2023', '1', 3, '2023-12-27 10:48:59', 1),
(4, 1, 'Games Design (Android/iOS)', '1681366555Games-Design.png', '&lt;p&gt;Kids will learn to design and build video games in a game design class. They will study game mechanics, user experience, and game design principles through..&lt;/p&gt;', 'Starts at 10 March, 2023', '1', 4, '2023-04-13 06:15:55', NULL),
(5, 1, 'The Internet of Things (IoT)', '1703673706iot.png', '&lt;p&gt;The Internet of Things (IoT) allows physical things to interact and remotely monitor, control, and automate processes and systems.&lt;/p&gt;', 'Starts at 10 March, 2023', '1', 5, '2023-12-27 10:43:22', 1),
(7, 1, 'Web development', '1681366734Web-development.png', '&lt;p&gt;In web development course for school kids, students will learn how to design and develop their own websites using HTML, CSS, and JavaScript.&lt;/p&gt;', ' Starts at 10 March, 2023', '1', 6, '2023-04-13 06:18:54', NULL),
(8, 1, 'Mechatronics', '1681366779Mechatronics.png', '&lt;p&gt;Mechatronics is an interdisciplinary field that combines mechanical, electrical, and computer engineering to create smart devices and machines.&lt;/p&gt;', ' Starts at 10 March, 2023', '1', 7, '2023-04-13 06:19:39', NULL),
(9, 1, 'Augmented Reality / virtual reality', '1681366828augmented-reality-irtual-reality.png', '&lt;p&gt;This course teaches youngsters about Augmented Reality (AR) and Virtual Reality (VR) technology, including its uses and differences.&lt;/p&gt;', ' Starts at 10 March, 2023', '1', 8, '2023-04-13 06:20:28', NULL),
(10, 2, 'Artificial intelligence with python', '1681367533Artificial-intelligence-with-python.png', '&lt;p&gt;This course is designed to introduce young learners to the fascinating world of AI and machine learning using the popular programming language,...&lt;/p&gt;', 'Starts at 10 March, 2023', '1', 9, '2023-04-13 06:32:13', NULL);

