INSERT INTO `tbl_courses_details` (`id`, `courses_id`, `block_content`, `block_order`, `status`, `add_date`) VALUES
(1, 1, '&lt;h3&gt;What you will learn:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Explain the operation and implementation of sensors, Arduino, and Dc motors and servo motors.&lt;/li&gt;\r\n&lt;li&gt;Describe different ways the sensors could be used.&lt;/li&gt;\r\n&lt;li&gt;Develop numerous projects using Arduino programming and excellent embedded system skills.&lt;/li&gt;\r\n&lt;li&gt;Look at the Arduino code used in projects and figure out what it does.&lt;/li&gt;\r\n&lt;/ul&gt;', 1, 1, '2023-03-27'),
(2, 1, '&lt;h3&gt;Course Overview&lt;/h3&gt;\r\n&lt;p&gt;Younger generations will be inspired to learn more about robotics and its applications by this course. In addition, this training seeks to develop young innovators.&lt;/p&gt;', 2, 1, '2023-03-27'),
(3, 1, '&lt;h3&gt;Why robotics?&lt;/h3&gt;\r\n&lt;p&gt;The industrial and cultural revolution we are currently in is fueled in large part by robotics, which will have a significant impact on economics in the near future. 90% of employment in the modern economy require some level of digital skill, according to the digital economy and society index. They are needed for more than just computer and coding occupations. More workers with creative and problem solving abilities will be required as robots and artificial intelligence replace &quot;simple&quot; tasks. However, there must be more to the implementation of robots in classrooms than just financial ones.&lt;/p&gt;', 3, 1, '2023-03-27'),
(4, 2, '&lt;h3&gt;What you will learn:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Design thinking: 3D printing allows youngsters to explore their creativity and design thinking skills. They can use digital tools to create 3D models and then print them into tangible objects.&lt;/li&gt;\r\n&lt;li&gt;Digital literacy: 3D printing requires the use of digital tools, such as computer-aided design (CAD) software. Youngsters can learn digital literacy skills by using these tools.&lt;/li&gt;\r\n&lt;li&gt;Problem-solving: 3D printing involves a lot of trial and error. Youngsters can learn how to identify and solve problems, such as improving the design or adjusting the printer settings.&lt;/li&gt;\r\n&lt;li&gt;Manufacturing processes: 3D printing is a form of additive manufacturing. Youngsters can learn about the different types of manufacturing processes and how they are used in industry.&lt;/li&gt;\r\n&lt;/ul&gt;', 1, 1, '2023-03-27'),
(5, 1, '&lt;h3&gt;Course Overview&lt;/h3&gt;\r\n&lt;p&gt;Kids who want to learn about 3D printing can take this course. They\'ll design and print 3D models and troubleshoot 3D printers using hands-on activities and digital tools. Problem-solving, design thinking, and digital literacy will also be learned. By the end of the course, they will comprehend STEAM fundamentals behind 3D printing and how it can be used in many industries.&amp;nbsp;&lt;/p&gt;', 2, 1, '2023-03-27'),
(6, 2, '&lt;h3&gt;Course Overview&lt;/h3&gt;\r\n&lt;p&gt;Kids who want to learn about 3D printing can take this course. They\'ll design and print 3D models and troubleshoot 3D printers using hands-on activities and digital tools. Problem-solving, design thinking, and digital literacy will also be learned. By the end of the course, they will comprehend STEAM fundamentals behind 3D printing and how it can be used in many industries.&amp;nbsp;&lt;/p&gt;', 2, 1, '2023-03-27'),
(7, 2, '&lt;h3&gt;Why 3D Printing what is the use ?&lt;/h3&gt;\r\n&lt;p&gt;3D printing lets kids practise their creative, problem-solving, and design thinking skills. CAD software helps them learn digital literacy. 3D printing is a fast-growing business that can prepare kids for employment. 3D printing is a fun way for kids to learn about technology and build valuable skills.&lt;/p&gt;', 3, 1, '2023-03-27'),
(8, 2, '&lt;ul&gt;\r\n&lt;li&gt;Beginner Friendly&lt;/li&gt;\r\n&lt;li&gt;High Quality Training&lt;/li&gt;\r\n&lt;li&gt;Project development skill&lt;/li&gt;\r\n&lt;li&gt;Gain excellent technical skills&lt;/li&gt;\r\n&lt;li&gt;Training Certificate&lt;/li&gt;\r\n&lt;/ul&gt;', 4, 1, '2023-03-27'),
(9, 2, '&lt;h3&gt;Who this course is for:&lt;/h3&gt;\r\n&lt;p&gt;3D printing is a fascinating technology that is suitable for students in 3rd to 10th grade. It allows youngsters to turn their ideas and designs into tangible objects through the use of digital tools and 3D printers. By learning about 3D printing, students can develop valuable skills, such as design thinking, problem-solving, and digital literacy.&lt;/p&gt;', 5, 1, '2023-03-27'),
(11, 2, '&lt;h3&gt;Pros&lt;/h3&gt;\r\n&lt;p&gt;Design thinking: 3D printing allows youngsters to explore their creativity and design thinking skills. They can use digital tools to create 3D models and then print them into tangible obj&lt;/p&gt;\r\n&lt;p&gt;Design thinking: 3D printing allows youngsters to explore their creativity and design thinking skills. They can use digital tools to create 3D models and then print them into tangible obj&lt;/p&gt;\r\n&lt;p&gt;Design thinking: 3D printing allows youngsters to explore their creativity and design thinking skills. They can use digital tools to create 3D models and then print them into tangible obj&lt;/p&gt;\r\n&lt;h3&gt;Cons&lt;/h3&gt;\r\n&lt;p&gt;Design thinking: 3D printing allows youngsters to explore their creativity and design thinking skills. They can use digital tools to create 3D models and then print them into tangible obj&lt;/p&gt;\r\n&lt;p&gt;Design thinking: 3D printing allows youngsters to explore their creativity and design thinking skills. They can use digital tools to create 3D models and then print them into tangible obj&lt;/p&gt;', 7, 1, '2023-03-27'),
(12, 2, '&lt;h3&gt;Pros jagadeesh one&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Design thinking: 3D printing allows youngsters to explore their creativity and design thinking skills. They can use digital tools to create 3D models and then print them into tangible obj&lt;/li&gt;\r\n&lt;/ul&gt;\r\n&lt;h3&gt;Cons jagadeesh onw&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Design thinking: 3D printing allows youngsters to explore their creativity and design thinking skills. They can use digital tools to create 3D models and then print them into tangible obj&lt;/li&gt;\r\n&lt;/ul&gt;', 8, 1, '2023-03-27'),
(13, 3, '&lt;h3&gt;What you will learn:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Programming and coding: Drones can be programmed to perform a variety of tasks, such as taking aerial photos or delivering packages. Youngsters can learn programming and coding skills to control the drone\'s movements and actions.&lt;/li&gt;\r\n&lt;li&gt;Problem-solving: Flying a drone can be challenging and requires problem-solving skills, such as adjusting to changing weather conditions or avoiding obstacles. Youngsters can learn how to identify and solve problems through hands-on experiences.&lt;/li&gt;\r\n&lt;li&gt;Geography and mapping: Drones can be used to capture aerial photos and videos that can be used for mapping and geographic analysis. Youngsters can learn about geography and mapping through analyzing and interpreting drone imagery.&lt;/li&gt;\r\n&lt;li&gt;Ethics and safety: Drones are subject to regulations and safety guidelines. Youngsters can learn about responsible drone usage and the ethical implications of drone technology.&lt;/li&gt;\r\n&lt;/ul&gt;', 1, 1, '2023-04-13'),
(14, 3, '&lt;h3&gt;Course Overview&lt;/h3&gt;\r\n&lt;p&gt;This UAV (drone) course is designed for kids who are interested in learning about the exciting world of aerial technology. They will learn how to control and program drones, as well as how to capture aerial photos and videos. Along the way, they will also develop problem-solving, design thinking, and digital literacy skills. By the end of the course, they will have a solid understanding of drone technology and how it can be used in various applications. This course is perfect for kids who want to explore their creativity, develop important skills, and have fun while learning about drone technology.&lt;/p&gt;', 2, 1, '2023-04-13'),
(15, 3, '&lt;h3&gt;Why UAV?&lt;/h3&gt;\r\n&lt;p&gt;Drone technology is a fun and inventive method for kids to explore the world. Drones let them explore new angles and capture stunning aerial footage. Drones can help kids acquire crucial life skills like creativity, problem-solving, and critical thinking. UAV technology is becoming increasingly significant in many industries and can show kids future employment options. UAV technology is a fun and engaging approach for kids to study and grow.&lt;/p&gt;', 3, 1, '2023-04-13'),
(16, 3, '&lt;h3&gt;Course Highlights:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Beginner Friendly&lt;/li&gt;\r\n&lt;li&gt;High Quality Training&lt;/li&gt;\r\n&lt;li&gt;Project development skill&lt;/li&gt;\r\n&lt;li&gt;Gain excellent technical skills&lt;/li&gt;\r\n&lt;li&gt;Training Certificate&lt;/li&gt;\r\n&lt;/ul&gt;', 4, 1, '2023-04-13'),
(17, 3, '&lt;h3&gt;Who this course is for:&lt;/h3&gt;\r\n&lt;p&gt;Drone technology is fun and innovative for 3rd&amp;ndash;10th graders. Kids can fly, programme, and take spectacular aerial photos and films with hands-on activities and digital tools. Creativity, problem-solving, and critical thinking will also help them grow personally and academically. Drones are used in agriculture, construction, and filmmaking, so kids can learn about them. They will grasp drone technology and its uses at the end of the course, which may inspire future career choices. This training is ideal for inquiring, adventurous kids interested in aviation technology.&lt;/p&gt;', 5, 1, '2023-04-13'),
(18, 4, '&lt;h3&gt;What you will learn:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;You will learn a wide range of skills related to creating video games. These may include programming, graphic design, storytelling, and project management.&lt;/li&gt;\r\n&lt;li&gt;You will learn how to use different software tools and programming languages to bring your ideas to life and create interactive gaming experiences.&lt;/li&gt;\r\n&lt;li&gt;You will also learn about game mechanics, user experience, and game design principles, which are critical to developing engaging and fun games.&lt;/li&gt;\r\n&lt;li&gt;You will develop important skills such as problem-solving, critical thinking, creativity, and collaboration, which are valuable in many areas of life.&lt;/li&gt;\r\n&lt;li&gt;You will have the ability to create your own video games and a solid understanding of the game design process.&lt;/li&gt;\r\n&lt;/ul&gt;', 1, 1, '2023-04-13'),
(19, 4, '&lt;h3&gt;Course Overview&lt;/h3&gt;\r\n&lt;p&gt;TKids will learn to design and build video games in a game design class. They will study game mechanics, user experience, and game design principles through hands-on activities and digital tools to make interesting and exciting games. Game creation requires programming, visual design, storytelling, and project management. Problem-solving, critical thinking, creativity, and cooperation will help them improve personally and academically. Kids will learn how to develop games and construct their own by the conclusion of the session. Gamers, techies, and creative kids will love this course.&lt;/p&gt;', 2, 1, '2023-04-13'),
(20, 4, '&lt;h3&gt;Why Games Design?&lt;/h3&gt;\r\n&lt;p&gt;Learning game designing at an early age can be beneficial for kids in many ways. Firstly, it can help develop their problem-solving, critical thinking, creativity, and collaboration skills, which are essential for success in many areas of life. Additionally, gaming is a popular and growing industry, and by learning game design at a young age, kids can set themselves up for potential future career opportunities. Moreover, creating their own video games can help boost their confidence and self-esteem, and it can be a fun and engaging way to introduce them to technology and digital arts. Finally, learning game design can help kids understand the digital world they are growing up in and make informed decisions about the games they play and the technology they use. Overall, learning game design in early age is a valuable experience that can help kids develop important skills and prepare them for their future.&lt;/p&gt;', 3, 1, '2023-04-13'),
(21, 4, '&lt;h3&gt;Course Highlights:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Beginner Friendly&lt;/li&gt;\r\n&lt;li&gt;High Quality Training&lt;/li&gt;\r\n&lt;li&gt;Project development skill&lt;/li&gt;\r\n&lt;li&gt;Gain excellent technical skills&lt;/li&gt;\r\n&lt;li&gt;Training Certificate&lt;/li&gt;\r\n&lt;/ul&gt;', 4, 1, '2023-04-13'),
(22, 4, '&lt;h3&gt;Who this course is for:&lt;/h3&gt;\r\n&lt;p&gt;Game Designing is a creative and engaging field that is suitable for students of all ages, including those in 3rd to 10th grade. As the gaming industry continues to grow, learning game design at a young age can also set students up for potential future career opportunities. Encouraging students to explore game design can help spark their curiosity and creativity while helping them develop important skills that will serve them well in the future.&lt;/p&gt;', 5, 1, '2023-04-13'),
(23, 5, '&lt;h3&gt;What you will learn:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;In an IoT course, students can learn about the different components of IoT systems, such as sensors, microcontrollers, and communication protocols.&lt;/li&gt;\r\n&lt;li&gt;They can also learn how to program and connect these devices to create smart systems that can automate tasks, monitor environments, and collect data.&lt;/li&gt;\r\n&lt;li&gt;Additionally, students can learn about the security and privacy implications of IoT systems and how to design and implement secure and ethical solutions.&lt;/li&gt;\r\n&lt;li&gt;By learning about IoT, students can develop skills in programming, electronics, and data analysis, which can be useful in a wide range of fields, including engineering, computer science, and business.&lt;/li&gt;\r\n&lt;li&gt;Overall, an IoT course can provide students with a fundamental understanding of the technology behind the connected devices they use in their everyday lives and prepare them for a future in which IoT is increasingly prevalent&lt;/li&gt;\r\n&lt;/ul&gt;', 1, 1, '2023-04-13'),
(24, 5, '&lt;h3&gt;Course Overview&lt;/h3&gt;\r\n&lt;p&gt;Young people can learn how to design and programme IoT systems utilising sensors, microcontrollers, and communication protocols in an IoT course. These systems can be used to automate chores, monitor environments, and collect data while also maintaining security and privacy in their IoT solutions.&lt;/p&gt;', 2, 1, '2023-04-13'),
(25, 5, '&lt;h3&gt;Why IoT?&lt;/h3&gt;\r\n&lt;p&gt;Early exposure to IoT can help children comprehend the importance of technology in our daily lives and how it can be applied to solve problems in the real world. Also, it can give students useful abilities like programming, electronics, and data analysis, which are highly sought-after in the current work market. Having a solid understanding of IoT can provide youngsters an advantage in their future careers due to the growing popularity of IoT devices in homes and companies.&lt;/p&gt;', 3, 1, '2023-04-13'),
(26, 5, '&lt;h3&gt;Course Highlights:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Beginner Friendly&lt;/li&gt;\r\n&lt;li&gt;High Quality Training&lt;/li&gt;\r\n&lt;li&gt;Project development skill&lt;/li&gt;\r\n&lt;li&gt;Gain excellent technical skills&lt;/li&gt;\r\n&lt;li&gt;Training Certificate&lt;/li&gt;\r\n&lt;/ul&gt;', 4, 1, '2023-04-13'),
(27, 5, '&lt;h3&gt;Who this course is for:&lt;/h3&gt;\r\n&lt;p&gt;Looking for an engaging and innovative course for your 3rd to 10th grade school kid? Look no further than our Internet of Things (IoT) course! Designed specifically for young learners, this course teaches the fundamentals of creating and programming IoT systems using sensors, microcontrollers, and communication protocols.&lt;/p&gt;\r\n&lt;p&gt;This course is perfect for young learners who want to explore the world of technology and gain valuable skills that will prepare them for future careers.&lt;/p&gt;', 5, 1, '2023-04-13'),
(28, 7, '&lt;h3&gt;What you will learn:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;In web development, learners will acquire the skills and knowledge necessary to create and design dynamic, responsive, and user-friendly websites.&lt;/li&gt;\r\n&lt;li&gt;This includes understanding how to structure and organize content using HTML, style and layout using CSS, and add interactivity and functionality using JavaScript.&lt;/li&gt;\r\n&lt;li&gt;Learners will also learn how to optimize websites for search engines, design mobile-first layouts, and integrate with third-party tools and services.&lt;/li&gt;\r\n&lt;li&gt;Additionally, they will gain experience in debugging, testing, and deploying websites to a server.&lt;/li&gt;\r\n&lt;li&gt;Through web development, learners can create and publish their own websites or contribute to larger-scale web projects.&lt;/li&gt;\r\n&lt;/ul&gt;', 1, 1, '2023-04-13'),
(29, 7, '&lt;h3&gt;Course Overview&lt;/h3&gt;\r\n&lt;p&gt;In web development course for school kids, students will learn how to design and develop their own websites using HTML, CSS, and JavaScript. They will start with the basics of web development such as HTML tags, CSS styles, and creating responsive layouts. They will also learn how to add interactivity to their websites using JavaScript and how to debug and test their code. Through various projects, students will have the opportunity to create their own websites from scratch and learn how to publish them to the internet. This course will help students develop important skills in problem-solving, critical thinking, and creativity while also introducing them to the world of technology and computer programming&lt;/p&gt;', 2, 1, '2023-04-13'),
(30, 7, '&lt;h3&gt;Why web development?&lt;/h3&gt;\r\n&lt;p&gt;Web development for kids at an early age can be a fun and engaging way to introduce them to the world of technology and coding. Through learning how to code websites using HTML, CSS, and JavaScript, kids can develop valuable skills such as problem-solving, critical thinking, and creativity. They can also gain a better understanding of how the internet and websites work.&lt;/p&gt;', 3, 1, '2023-04-13'),
(31, 7, '&lt;h3&gt;Course Highlights:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Beginner Friendly&lt;/li&gt;\r\n&lt;li&gt;High Quality Training&lt;/li&gt;\r\n&lt;li&gt;Project development skill&lt;/li&gt;\r\n&lt;li&gt;Gain excellent technical skills&lt;/li&gt;\r\n&lt;li&gt;Training Certificate&lt;/li&gt;\r\n&lt;/ul&gt;', 4, 1, '2023-04-13'),
(32, 7, '&lt;h3&gt;Who this course is for:&lt;/h3&gt;\r\n&lt;p&gt;Web development is an important skill for students in 3rd to 10th grade to learn. It involves creating websites and web applications using programming languages such as HTML, CSS, and JavaScript.&lt;/p&gt;', 5, 1, '2023-04-13'),
(33, 7, '&lt;h3&gt;Who this course is for:&lt;/h3&gt;\r\n&lt;p&gt;Web development is an important skill for students in 3rd to 10th grade to learn. It involves creating websites and web applications using programming languages such as HTML, CSS, and JavaScript.&lt;/p&gt;', 5, 1, '2023-04-13'),
(34, 8, '&lt;h3&gt;What you will learn:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;In mechatronics, students learn about the design, construction, and operation of advanced systems that integrate these different components.&lt;/li&gt;\r\n&lt;li&gt;They also learn about programming and software development, as well as how to use sensors and other technology to create intelligent machines that can interact with their environment.&lt;/li&gt;\r\n&lt;li&gt;Mechatronics is an exciting field with many practical applications, such as in manufacturing, transportation, and healthcare.&lt;/li&gt;\r\n&lt;li&gt;By learning about mechatronics, students can develop valuable skills in critical thinking, problem-solving, and teamwork.&lt;/li&gt;\r\n&lt;/ul&gt;', 1, 1, '2023-04-13'),
(35, 8, '&lt;h3&gt;Course Overview&lt;/h3&gt;\r\n&lt;p&gt;Mechatronics is an interdisciplinary field that combines mechanical, electrical, and computer engineering to create smart devices and machines. In this course, kids will learn how to design, build, and program robots and other automated systems using sensors, motors, microcontrollers, and programming languages. They will also gain knowledge about electronics, mechanics, and computer science concepts. Through hands-on projects and problem-solving challenges, students will develop skills such as critical thinking, teamwork, and creativity while exploring the exciting world of mechatronics.&lt;/p&gt;', 2, 1, '2023-04-13'),
(36, 8, '&lt;h3&gt;Why Mechatronics?&lt;/h3&gt;\r\n&lt;p&gt;Learning Mechatronics at an early age provides kids with a valuable opportunity to develop problem-solving skills, logical thinking, and creativity, as they learn to design and build robots and other mechanical devices that interact with their environment. This skill set can be applied to a wide range of fields, from entertainment to manufacturing to healthcare, and can also help foster an interest in technology and engineering. Additionally, working with robotics and other hands-on activities can provide a fun and engaging way for kids to learn and explore new concepts, while also promoting teamwork and collaboration.&lt;/p&gt;', 3, 1, '2023-04-13'),
(37, 8, '&lt;h3&gt;Course Highlights:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Beginner Friendly&lt;/li&gt;\r\n&lt;li&gt;High Quality Training&lt;/li&gt;\r\n&lt;li&gt;Project development skill&lt;/li&gt;\r\n&lt;li&gt;Gain excellent technical skills&lt;/li&gt;\r\n&lt;li&gt;Training Certificate&lt;/li&gt;\r\n&lt;/ul&gt;', 4, 1, '2023-04-13'),
(38, 8, '&lt;h3&gt;Who this course is for:&lt;/h3&gt;\r\n&lt;p&gt;Mechatronics is a fascinating field that combines mechanics, electronics, and computing. It is an ideal field for kids in 3rd to 10th grade who are interested in robotics and engineering. This field is also a great way to introduce kids to the concept of automation and its applications in the real world. Encouraging kids to explore this field can help spark their curiosity and interest in robotics and engineering.&lt;/p&gt;', 5, 1, '2023-04-13'),
(39, 9, '&lt;h3&gt;What you will learn:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Youngsters will learn how to create and program immersive digital experiences that can be used in various industries, such as gaming, education, healthcare, and entertainment.&lt;/li&gt;\r\n&lt;li&gt;They will learn how to design and develop 3D models, integrate audio and visual effects, and code interactive experiences using platforms such as Unity, Vuforia, and ARCore.&lt;/li&gt;\r\n&lt;li&gt;They will also learn about the differences between AR and VR, their applications, and how to create experiences that can be viewed on a variety of devices, such as smartphones and VR headsets.&lt;/li&gt;\r\n&lt;/ul&gt;', 1, 1, '2023-04-13'),
(40, 9, '&lt;h3&gt;What you will learn:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Youngsters will learn how to create and program immersive digital experiences that can be used in various industries, such as gaming, education, healthcare, and entertainment.&lt;/li&gt;\r\n&lt;li&gt;They will learn how to design and develop 3D models, integrate audio and visual effects, and code interactive experiences using platforms such as Unity, Vuforia, and ARCore.&lt;/li&gt;\r\n&lt;li&gt;They will also learn about the differences between AR and VR, their applications, and how to create experiences that can be viewed on a variety of devices, such as smartphones and VR headsets.&lt;/li&gt;\r\n&lt;/ul&gt;', 1, 1, '2023-04-13'),
(41, 9, '&lt;h3&gt;Course Overview&lt;/h3&gt;\r\n&lt;p&gt;This course teaches youngsters about Augmented Reality (AR) and Virtual Reality (VR) technology, including its uses and differences. Students will also use popular software tools to develop AR and VR experiences and explore the potential of these technologies in gaming, education, and healthcare. They will also learn how to ethically use AR and VR technology and its ethical and societal implications.&lt;/p&gt;', 2, 1, '2023-04-13'),
(42, 9, '&lt;h3&gt;Why Augmented Reality / virtual reality?&lt;/h3&gt;\r\n&lt;p&gt;Augmented Reality and Virtual Reality are rapidly growing technologies and have a lot of potential for various industries in the future. By introducing these technologies to kids at an early age, they can develop a fundamental understanding of how these technologies work and the various possibilities that they offer. Additionally, learning about these technologies can also foster creativity and imagination in kids, as they can design and create their own AR/VR experiences. It can also enhance their learning experience as they can explore and visualize complex concepts in a more interactive and engaging manner&lt;/p&gt;', 3, 1, '2023-04-13'),
(43, 9, '&lt;h3&gt;Course Highlights:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Beginner Friendly&lt;/li&gt;\r\n&lt;li&gt;High Quality Training&lt;/li&gt;\r\n&lt;li&gt;Project development skill&lt;/li&gt;\r\n&lt;li&gt;Gain excellent technical skills&lt;/li&gt;\r\n&lt;li&gt;Training Certificate&lt;/li&gt;\r\n&lt;/ul&gt;', 4, 1, '2023-04-13'),
(44, 9, '&lt;h3&gt;Who this course is for:&lt;/h3&gt;\r\n&lt;p&gt;AR and VR can enhance learning for 3rd&amp;ndash;10th graders. AR overlays digital visuals on the actual world, whereas VR creates an immersive virtual reality. These technologies can be used to recreate historical events, explore the human body in 3D, or practise coding in a pleasant and engaging way. AR and VR make learning fun and effective for kids. AR and VR will change how 3rd&amp;ndash;10th graders see the world.&lt;/p&gt;', 5, 1, '2023-04-13'),
(45, 10, '&lt;h3&gt;What you will learn:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Build intelligent systems and algorithms using Python programming language.&lt;/li&gt;\r\n&lt;li&gt;Understand the ethical implications of AI and develop a responsible approach to designing and deploying intelligent systems.&lt;/li&gt;\r\n&lt;li&gt;Understand the basics of machine learning and deep learning and how they can be applied to solve real-world problems.&lt;/li&gt;\r\n&lt;li&gt;Work on real-world projects and build a portfolio of AI projects to showcase their skills to potential employers or universities.&lt;/li&gt;\r\n&lt;/ul&gt;', 1, 1, '2023-04-13'),
(46, 10, '&lt;h3&gt;Course Overview&lt;/h3&gt;\r\n&lt;p&gt;This course is designed to introduce young learners to the fascinating world of AI and machine learning using the popular programming language, Python. By the end of the course, students will have a foundational understanding of how AI works and how to create basic AI applications using Python.&lt;/p&gt;', 2, 1, '2023-04-13'),
(47, 10, '&lt;h3&gt;Why Artificial intelligence?&lt;/h3&gt;\r\n&lt;p&gt;Artificial intelligence (AI) is becoming more and more important today and will do so in the future. Young people can therefore better prepare for professions in a rapidly changing environment by learning about AI and its applications.&lt;/p&gt;\r\n&lt;p&gt;Learning about AI can be an excellent opportunity for young people to develop valuable skills and prepare themselves for the future.&lt;/p&gt;', 3, 1, '2023-04-13'),
(48, 10, '&lt;h3&gt;Course Highlights:&lt;/h3&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Beginner Friendly&lt;/li&gt;\r\n&lt;li&gt;High Quality Training&lt;/li&gt;\r\n&lt;li&gt;Project development skill&lt;/li&gt;\r\n&lt;li&gt;Gain excellent technical skills&lt;/li&gt;\r\n&lt;li&gt;Training Certificate&lt;/li&gt;\r\n&lt;/ul&gt;', 4, 1, '2023-04-13'),
(49, 10, '&lt;h3&gt;Who this course is for:&lt;/h3&gt;\r\n&lt;p&gt;Artificial Intelligence is a captivating field that is appropriate for all ages, including 3rd to 10th graders. Learning about AI at a young age can help develop valuable skills, such as critical thinking and problem-solving, and prepare them for future career opportunities in a world that relies on technology. Encouraging students to explore the topic of AI can spark their interest and curiosity in technology.&lt;/p&gt;', 5, 1, '2023-04-13');

