(2, '', 'index.php', 'Home', '', '', '', 1, 1, '2023-03-27 05:53:08', 0, 1, 0),
(3, 'megamenu', 'about.php', 'About', '', 'about-img-2.png', '&lt;h2&gt;EDUEME Research Labs&lt;/h2&gt;\r\n&lt;p&gt;The pace of technical development in the modern world is accelerating more quickly than before. Adaptation and the acquisition of new competencies and skills are crucial in this continuously changing world. All citizens&amp;mdash;young and old&amp;mdash;are impacted by the advancement of digital technology and the digitalization of society.&lt;/p&gt;\r\n&lt;p&gt;Everyday life is greatly influenced by the use of mobile phones, laptops, tablets, and other technologies that serve both social and entertainment purposes. For everyone to be able to engage the digital generation in the educational process, they must learn to adapt to a changing world and build their digital competencies.&lt;/p&gt;\r\n&lt;p&gt;Our future generation is now in need to learn about these machines to be future ready, same like in the past where Indian Schools between 1970 and 1990 used to have Occupational Courses for their students to be ready for 21st century. We at Edueme take extensive care of providing Work-Oriented learning opportunities to our students to make them ready for 2nd half of 21st century.&lt;/p&gt;\r\n&lt;p&gt;Our team includes research scientists, innovators, Physicists, who has extensive knowledge and rich experience in the areas of Robotics, Mechanical Design, Machine Learning, Artificial Intelligence. We are the first in India to introduce component based robotics from 3rd standard.&lt;/p&gt;', 2, 1, '2023-03-27 05:53:50', NULL, 1, 0),
(4, 'megamenu', 'services.php', 'Services', '', '', '&lt;p&gt;Children will learn everything they need to know to code their own robotics projects using the Arduino, the industry-leading virtual microcontroller. With the aid of block-based online coding interfaces that are simple to use, children receive a very capable and rewarding introduction to robotics. Basic circuitry and programming principles are also addressed to provide students with a solid basis for eventual study of more complicated components and programming structures.&lt;/p&gt;\r\n&lt;div class=&quot;n-three-card-main wp &quot;&gt;&amp;nbsp;&lt;/div&gt;', 3, 1, '2023-03-27 05:54:19', 1, 1, 0),
(5, 'megamenu', 'courses.php', 'Courses', '', '', '', 4, 1, '2023-03-27 05:54:35', NULL, 1, 0),
(6, 'megamenu', 'events.php', 'Events', '', '', '', 5, 1, '2023-03-27 05:54:55', 1, 1, 0),
(7, 'megamenu', 'contact.php', 'Contact', '', '', '', 6, 1, '2023-03-27 05:55:16', NULL, 1, 0),
(8, '', 'index.php', 'Feautred Services', '', '', '&lt;p&gt;Edueme provides cutting-edge learning resources to inspire the next generation of innovators. Our specialists created a complete robotics and AI curriculum that spans programming, circuit design, mechanical engineering, and machine learning. We provide beginning to expert training for all ages and ability levels. Our courses are enjoyable and interesting, whether you\'re interested in robotics or artificial intelligence. Edueme offers interactive lectures, hands-on projects, and real-world applications to help you comprehend robotics and AI.&lt;/p&gt;\r\n&lt;p&gt;We offer reasonable prices and flexible scheduling to make learning accessible to everyone. Our staff offers tailored support to help you reach your learning goals and flourish in the future. We invite students, educators, and lifelong learners to join our robotics and AI community and explore the unlimited possibilities of these intriguing subjects. Learn about our courses, resources, and events on our website and start your robotics and AI career now.&lt;/p&gt;', 21, 1, '2023-04-12 12:57:10', 1, NULL, 0),
(9, '', 'index.php', 'Innovative', '', '', '&lt;h2&gt;Advance Your career and lear something New&lt;/h2&gt;\r\n&lt;p&gt;Edueme offers robotics and AI programmes to boost careers and knowledge. Industry specialists teach beginner-to-advanced courses. The programmes offer hands-on learning, flexible scheduling, customised support, and economical cost.&lt;/p&gt;\r\n&lt;p&gt;Joining our community of learners allows people to explore new career paths in robotics and AI and develop the skills and information needed to succeed in this fast-growing industry.&lt;/p&gt;', 22, 1, '2023-04-12 13:05:01', NULL, NULL, 0),
(10, '', 'index.php', 'Occurrence', '', '', '&lt;h2&gt;Find Out More About Learning Experience&lt;/h2&gt;\r\n&lt;p&gt;Learning experiences, which might include formal schooling, unstructured learning chances, or practical experiences, are a variety of activities intended to promote development and learning. Informal learning experiences are less structured and happen on their own, whereas formal education and training programmes have a set curriculum. Learners are given the chance to apply their knowledge in real-world situations through hands-on activities. Whatever the case, it\'s essential to maintain an open mind and a curiosity in order to learn, develop, and attain goals.&lt;/p&gt;', 23, 1, '2023-04-12 13:10:13', NULL, NULL, 0),
(11, '', 'Home-Chronicle', 'Chronicle', '', '', '&lt;h2&gt;Our Latest Blogs&lt;/h2&gt;\r\n&lt;p&gt;Through our often updated blog, Edueme is committed to informing our community of learners about the most recent advancements in robotics and artificial intelligence. New technology, market trends, and career advice are just a few of the topics that our knowledgeable writers and researchers cover. All levels of learners can access the blog, and those who are interested can discover the most recent entries on the organization\'s website or sign up for our newsletter to receive updates. In order to keep our audience informed and interested in the fascinating and rapidly developing field of robots and AI, we at Eduemeresearchlabs.com.&lt;/p&gt;', 24, 1, '2023-04-12 13:15:12', NULL, NULL, 0),
(14, '', 'home-blog', 'Blog', '', '', '', 34, 1, '2023-04-12 20:36:02', 1, 0, 0),
(15, '', 'footer', 'Purchase guide', '', 'banner-img-1.png', '&lt;h2&gt;EDUEME Research Labs&lt;/h2&gt;\r\n&lt;p&gt;The pace of technical development in the modern world is accelerating more quickly than before. Adaptation and the acquisition of new competencies and skills are crucial in this continuously changing world. All citizens&amp;mdash;young and old&amp;mdash;are impacted by the advancement of digital technology and the digitalization of society.&lt;/p&gt;\r\n&lt;p&gt;Everyday life is greatly influenced by the use of mobile phones, laptops, tablets, and other technologies that serve both social and entertainment purposes. For everyone to be able to engage the digital generation in the educational process, they must learn to adapt to a changing world and build their digital competencies.&lt;/p&gt;\r\n&lt;p&gt;Our future generation is now in need to learn about these machines to be future ready, same like in the past where Indian Schools between 1970 and 1990 used to have Occupational Courses for their students to be ready for 21st century. We at Edueme take extensive care of providing Work-Oriented learning opportunities to our students to make them ready for 2nd half of 21st century.&lt;/p&gt;\r\n&lt;p&gt;Our team includes research scientists, innovators, Physicists, who has extensive knowledge and rich experience in the areas of Robotics, Mechanical Design, Machine Learning, Artificial Intelligence. We are the first in India to introduce component based robotics from 3rd standard.&lt;/p&gt;', 56, 1, '2023-04-12 21:07:56', NULL, 0, 1),
(16, '', 'footer', 'Privacy policy', '', '', '&lt;h2&gt;EDUEME Privacy policy&lt;/h2&gt;\r\n&lt;p&gt;The pace of technical development in the modern world is accelerating more quickly than before. Adaptation and the acquisition of new competencies and skills are crucial in this continuously changing world. All citizens&amp;mdash;young and old&amp;mdash;are impacted by the advancement of digital technology and the digitalization of society.&lt;/p&gt;\r\n&lt;p&gt;Everyday life is greatly influenced by the use of mobile phones, laptops, tablets, and other technologies that serve both social and entertainment purposes. For everyone to be able to engage the digital generation in the educational process, they must learn to adapt to a changing world and build their digital competencies.&lt;/p&gt;\r\n&lt;p&gt;Our future generation is now in need to learn about these machines to be future ready, same like in the past where Indian Schools between 1970 and 1990 used to have Occupational Courses for their students to be ready for 21st century. We at Edueme take extensive care of providing Work-Oriented learning opportunities to our students to make them ready for 2nd half of 21st century.&lt;/p&gt;\r\n&lt;p&gt;Our team includes research scientists, innovators, Physicists, who has extensive knowledge and rich experience in the areas of Robotics, Mechanical Design, Machine Learning, Artificial Intelligence. We are the first in India to introduce component based robotics from 3rd standard.&lt;/p&gt;', 45, 1, '2023-04-12 21:18:03', NULL, 0, 1);

