INSERT INTO `tbl_mjcet_first_submenu` (`menuId`, `menuType`, `menuSulg`, `menuName`, `menuTitle`, `menuDocument`, `menuOrder`, `menuContent`, `menuContentTwo`, `menuImage`, `status`, `addOn`) VALUES
(1, '2', 'our-chairman', 'GC Chairman', '', '', 1, '&lt;h2&gt;Honorary Secretary,&lt;br /&gt;SUES &amp;amp; Chairman,&lt;br /&gt;Governing Council, MJCET&lt;/h2&gt;\r\n&lt;div class=&quot;clear&quot;&gt;&amp;nbsp;&lt;/div&gt;\r\n&lt;h3&gt;Mr. Zafar Javeed&lt;/h3&gt;', '&lt;p&gt;The Sultan-ul-Uloom Education Society, was established in 1980 by former bureaucrats and well known philanthropists, with the intention of setting up institutions imparting quality education from the Primary School level onwards. In 1980, the Society established the Muffakham Jah College of Engineering, which within a very short span of time, emerged as a leading and prestigious Engineering College, in the erstwhile State of Andhra Pradesh. The Founders of the Society, were on a mission and had a clear vision of filling the urgent void for establishing institutions in niche areas of Technology. Very soon under the aegis of Sultan-ul-Uloom Education Society, College of Education, College of Management, College of Law, College of Pharmacy, Junior College etc. were established. These institutions over the span of forty years have grown is reputation both at the State and also at the National level, as institutes of very high academic standards. Almost all the Constituent Institutions run by the Society have accreditation from the &amp;ldquo;National Board of Accreditation&amp;rdquo; and &quot;National Assessment and Accreditation Council&quot; and have won innumerable awards from the National Assessment Boards and Ministry of Human Resource Development etc. Leading national magazines and newspapers such as India Today, Outlook, The Week and the Times of India have ranked &quot;Muffakham Jah College of Engineering and Technology&quot; in the Top Engineering Colleges of the Country. The Society firmly believes in establishing courses in specialisation and in niche areas and in this pursuit have established Masters courses in Education, Law Management, Pharmacy and Engineering. Today, the Society has institutions from Nursery to Research Centers offering Ph.D, recognised by the Osmania University. To keep abreast with the evolving technology, we have introduced futuristic course like Artificial Intelligence &amp;amp; Data Science and Artificial Intelligence and Machine Learning. Sultan-ul-Uloom Education Society, perhaps as a group has most accredited institutions under its aegis at the national level. As our commitment to the underprivileged sections of the Society, we have established Six Schools in areas which do not have quality institutions in the vicinity and offer education at highly subsidised fee structure. Our resolve and commitment to achieving High Standards of Education gets stronger by the day and we dedicate ourselves to improvement in quality with each passing day.&lt;/p&gt;\r\n&lt;h3&gt;GOVERNING COUNCIL MEMBERS, MJCET&lt;/h3&gt;\r\n&lt;table class=&quot;table-1&quot;&gt;\r\n&lt;tbody&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;Mr. Zafar Javeed Hon. Secretary, SUES&lt;/td&gt;\r\n&lt;td&gt;Chairman, G.C.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;Mr. Syed Abdul Wahab&lt;/td&gt;\r\n&lt;td&gt;Member, G.C.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;Dr. Mir Akbar Ali Khan Treasurer, SUES&lt;/td&gt;\r\n&lt;td&gt;Member, G.C.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;Mr.Masood Abdul Khader, Joint secretary, SUES&lt;/td&gt;\r\n&lt;td&gt;Member, G.C.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;Mr. Nisar Ahmed&lt;/td&gt;\r\n&lt;td&gt;Member, G.C.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;Mr. Abdul Aleem Khan&lt;/td&gt;\r\n&lt;td&gt;Member, G.C.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;Dr. Mir Khalid Ali&lt;/td&gt;\r\n&lt;td&gt;Member, G.C.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;Dr. Mohammed Ibrahim Ali Siddiqui&lt;/td&gt;\r\n&lt;td&gt;Special Invitee&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;Mr. Syed Aamer Javeed&lt;/td&gt;\r\n&lt;td&gt;Special Invitee&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;Mr. Sarwar Ali Khan&lt;/td&gt;\r\n&lt;td&gt;Special Invitee&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;Dr. Basheer Ahmed Advisor-cum-Director&lt;/td&gt;\r\n&lt;td&gt;Convenor, G. C.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;/tbody&gt;\r\n&lt;/table&gt;\r\n&lt;h3&gt;BOARD OF GOVERNORS, SUES&lt;/h3&gt;\r\n&lt;table class=&quot;table-1&quot;&gt;\r\n&lt;tbody&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;Mr. Mohammed Waliulla&lt;/td&gt;\r\n&lt;td&gt;Chairman&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;Mr. Syed Abdul Wahab&lt;/td&gt;\r\n&lt;td&gt;Vice-Chairman&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;Mr. Zafar Javeed&lt;/td&gt;\r\n&lt;td&gt;Honorary Secretary&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;Mr. Masood Abdul Khader&lt;/td&gt;\r\n&lt;td&gt;Joint Secretary&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;Dr. Mir Akbar Ali Khan&lt;/td&gt;\r\n&lt;td&gt;Treasurer&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;Mr. Nisar Ahmed&lt;/td&gt;\r\n&lt;td&gt;Member&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;Mr. Mohammed Ibrahim Ali Siddiqui&lt;/td&gt;\r\n&lt;td&gt;Member&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;Dr. Aslam M. Khan&lt;/td&gt;\r\n&lt;td&gt;Member&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;Mr. Syed Aamer Javeed&lt;/td&gt;\r\n&lt;td&gt;Member&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;Mr. Akheel Ahmed&lt;/td&gt;\r\n&lt;td&gt;Member&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;/tbody&gt;\r\n&lt;/table&gt;', 'gc-chairman.png', '1', '2022-12-19 11:08:37'),
(2, '2', 'sues-history', 'SUES History', '', '', 2, '&lt;div class=&quot;heading-bg-1&quot;&gt;&lt;br /&gt;&lt;br /&gt;\r\n&lt;h2&gt;SUES History&lt;/h2&gt;\r\n&lt;div class=&quot;clear&quot;&gt;&amp;nbsp;&lt;/div&gt;\r\n&lt;p&gt;The Sultan-ul-Uloom Education Society was established in the year 1980 with a philanthropic conviction of imparting high-quality education to students at different levels.&lt;/p&gt;\r\n&lt;p&gt;It is a premier Education Society with a venerable legacy and undeniable acclaim for the highest academic standards, diverse educational and research programmes, distinguished faculty, illustrious alumni, modern infrastructure, and a beautifully landscaped lush green campus.&lt;/p&gt;\r\n&lt;h3&gt;Our Rich Legacy&lt;/h3&gt;\r\n&lt;/div&gt;\r\n&lt;p&gt;Sultan-ul-Uloom Education Society was founded on the rich tradition of culture, enterprise, and sound values, characteristic of the founding members - each an accomplished and successful individual in his own right. Motivated by a strong desire to provide students of diverse social and cultural backgrounds with the opportunity to enjoy quality education that would eventually lead to the upliftment of society as a whole, the Society offers education in various disciplines, ranging from Engineering and Technology to Business Administration, Law, Pharmacy and more.&lt;/p&gt;', '', 'sues-history-banner.png', '1', '2022-12-19 11:10:41'),
(4, '2', 'about-mjcet', 'About MJCET', 'About MJCET', '', 3, '&lt;h2&gt;About MJCET&lt;/h2&gt;\r\n&lt;div class=&quot;clear&quot;&gt;&amp;nbsp;&lt;/div&gt;\r\n&lt;h3&gt;Muffakham Jah College of Engineering and Technology&lt;/h3&gt;', '&lt;p&gt;Established in 1980, the Muffakham Jah College of Engineering and Technology is a premier institute of its kind, offering four year B.E. degree courses in 8 Engineering branches, namely, Civil Engineering, Computer Science Engineering, Electrical and Electronics Engineering, Electronics and Communication Engineering, Information Technology, Mechanical Engineering, Artificial Intelligence &amp;amp; Data Science, Artificial Intelligence &amp;amp; Machine Learning and five post graduate courses in M.E. (CAD/CAM), M.E. (Structural Engineering), M.E. (Digital Systems), M. Tech. (Computer Science), M.E. (Power Electronic Systems) of two years duration. The College is affiliated to the Osmania University and is approved by the AICTE.&lt;/p&gt;', 'sues-history-banner.png', '1', '2022-12-29 16:14:42'),
(5, '2', 'strategic-plan', 'Strategic Plan', 'Muffakham Jah College of Engineering and Technology', '', 4, '&lt;p&gt;Content will be posted soon..&lt;/p&gt;', '', 'sues-history-banner.png', '1', '2023-01-03 11:41:32'),
(6, '2', 'institutions-core-values', 'Core Values', 'Of the Institution', '', 5, '&lt;ul&gt;\r\n&lt;li&gt;Academic integrity through honest, fair and ethical and transparent processes&lt;/li&gt;\r\n&lt;li&gt;Excellence in teaching-learning through student centric pedagogy and state of the art facilities&lt;/li&gt;\r\n&lt;li&gt;Tolerance for diversity among the faculty and students through freedom and respect for everyone without discrimination&lt;/li&gt;\r\n&lt;li&gt;Interdisciplinary interaction through elective courses, projects and R &amp;amp; D work&lt;/li&gt;\r\n&lt;li&gt;Faculty Development through support for qualification improvement, research, innovation and publications&lt;/li&gt;\r\n&lt;li&gt;Student development by nourishing creativity, imparting life skills and instilling social responsibility.&lt;/li&gt;\r\n&lt;/ul&gt;', '', 'sues-history-banner.png', '1', '2023-01-03 11:43:50'),
(7, '2', '', 'Organisational Structure', 'Organisational Structure', 'OrganisationalStructure.pdf', 6, '', '', '', '1', '2023-01-03 11:44:42'),
(8, '2', 'other-institutions', 'Other Institutions', 'Other Institutions', '', 7, '', '', '', '1', '2023-01-03 11:45:11'),
(9, '2', 'advisor-cum-director', 'Advisor cum Director', 'Prof. Basheer Ahmed', '', 8, '&lt;p&gt;Prof. Basheer Ahmed holds BE degree in Mechanical Engineering, Masters in Robotics and Automation and Doctorate in Flexible Manufacturing Systems. He joined BHEL in 1972 as an engineer and serving in various administrative capacities retired as General Manager and In charge of Technology Development Laboratory in 2007. During his service of more than three decades at BHEL he acquired many distinguished honours such as &amp;ldquo;The BHEL Excellence Award&amp;rdquo;, &amp;ldquo;Achievement Award-Industry&amp;rdquo; at First International and 22nd AIMTDR Conference held at IIT Roorkee for his contributions in the field of automation and manufacturing. He also served as a member of DST &amp;ndash; PAC Committee on Robotics and Automation for a period of three years. He has 03 Indian Patents granted and 50 National and International publications to his credit.&lt;/p&gt;\r\n&lt;p&gt;After superannuation from BHEL, he joined MJCET as Principal in 2007. During his tenure as principal from 2007 to 2012, leveraging his industrial acumen, he brought many academic reforms in the MJCET. He played a key role in faculty qualification improvement by introducing Study Leave to pursue M.E./M.Tech and Ph.D. With this initiative, now MJCET has 61 doctorates and all faculty members are with master&amp;rsquo;s degree and 77 members are pursuing their PhD. Later he took charge as Advisor cum Director in the year 2013. Under his able leadership as head of the institute, MJCET got 5 research centres approved by Osmania University, in which 68 PhD scholars are pursuing their doctorate. He was instrumental in creating a research and development ecosystem at MJCET by establishing R &amp;amp; D Cell and getting 10% of Annual Budget allocation by SUES to spend as R &amp;amp; D grants for projects. Two of the successfully completed R &amp;amp; D projects have been granted Indian Patent by Government of India and another four projects are in pipeline for the grant. Under his seasoned administrative leadership, MJCET has developed various state of the art laboratories and other infrastructure facilities. In order to bridge the gap between Industry and Academia, he emphasized on signing MoUs with Industry and providing training to improve employability of students which resulted in excellent placements and internships in various MNCs. Under his tutelage, MJCET has grown leaps and bounds in academics and research orientation, and has attracted greater visibility in the state and national landscape.&lt;/p&gt;', '', 'advisor-cum-director.png', '1', '2023-01-03 11:46:10'),
(10, '2', 'principal', 'Principal', 'Dr. Mahipal Singh Rawat', '', 9, '&lt;p&gt;Dr Mahipal Singh Rawat Graduated from the University of Roorkee (Now IIT-R) in 1983 and was the recipient of the Thomson award for securing a second position. Joined BHEL Corporate R&amp;amp;D Hyderabad in 1983 and completed a PhD from IIT Bombay on &amp;ldquo;Role of Residual Stresses on Life of 12% Cr Steel Used in Thermal Power Plants&amp;rdquo; in 2002. He completed MBA (HR) from IGNOU and diploma on &amp;ldquo;Quality Reliability and Operations Research&amp;rdquo; from Indian Statistical Institute, Madras.&lt;/p&gt;\r\n&lt;p&gt;He started his career at BHEL Corporate R &amp;amp; D Hyderabad undertaking several developmental projects in the area of Non-destructive testing of power plant components and carried out a number of Failure Investigations &amp;amp; Residual Life Assessment Studies. He has four patents to the credit and contributed a number of technical papers in National and International seminars as well as journals. His papers have been published in Scopus and Web of Science. He also successfully completed a project titled &amp;ldquo;Castability studies of castings for Advanced Ultra Super Critical Power Plant (AUSC)&amp;rdquo; as the Principal Investigator. The project was completed under the supervision of the office of Principal Scientific Adviser to Prime Minister.&lt;/p&gt;\r\n&lt;p&gt;Dr Rawat is a trained NDT personnel and has received training in various non-destructive evaluation techniques at EPRI USA, IRIS USA and Physical Acoustics UK. During his tenure at Corporate R&amp;amp;D Hyderabad, has guided a number of M.Tech students mainly from NIT Warangal and is currently a supervisor for the PhD student of Jawaharlal Nehru Technological University (JNTU), Hyderabad. He also had been a reviewer for International Journal of Industrial Chemistry.&lt;/p&gt;\r\n&lt;p&gt;Being superannuated from BHEL as the General Manager in August 2019, he joined Greater Noida Institute of Technology (GNIOT), Greater Noida as a Professor &amp;amp; Head, Mechanical Engineering Department. As the conference coordinator at GNIOT he successfully organized International e-Conference on &amp;ldquo;Cutting Edges in Mechanical Engineering&amp;rdquo; on February 20, 2021dinator. He joined MJCET as thePrincipal on 15th Nov 2021.&lt;/p&gt;', '', 'principal.png', '1', '2023-01-03 11:46:40'),
(11, '5', 'academics-calendar', 'Academics Calendar', 'Academics Calendar', '', 1, '&lt;div class=&quot;tabset&quot;&gt;&lt;!-- Tab 1 --&gt; &lt;input id=&quot;tab1&quot; checked=&quot;checked&quot; name=&quot;tabset&quot; type=&quot;radio&quot; /&gt; &lt;label for=&quot;tab1&quot;&gt;B.E. Almanac 2021-22&lt;/label&gt; &lt;!-- Tab 2 --&gt; &lt;input id=&quot;tab2&quot; name=&quot;tabset&quot; type=&quot;radio&quot; /&gt; &lt;label for=&quot;tab2&quot;&gt;M.E./M.Tech Almanac 2021-22&lt;/label&gt; &lt;!-- Tab 3 --&gt;\r\n&lt;div class=&quot;tab-panels&quot;&gt;\r\n&lt;section id=&quot;marzen&quot; class=&quot;tab-panel&quot;&gt;\r\n&lt;div class=&quot;table-scroll-1&quot;&gt;\r\n&lt;table class=&quot;annual-report-table-1&quot;&gt;\r\n&lt;tbody&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;S.No&lt;/td&gt;\r\n&lt;td&gt;Year&lt;/td&gt;\r\n&lt;td&gt;Download&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;01&lt;/td&gt;\r\n&lt;td&gt;\r\n&lt;div class=&quot;skew-1&quot;&gt;2019-2020&lt;/div&gt;\r\n&lt;/td&gt;\r\n&lt;td&gt;&lt;a href=&quot;documents/B.E-Almanac-2019-2020.pdf&quot; target=&quot;_blank&quot;&gt;&lt;img src=&quot;images/pdf-download.svg&quot; /&gt;&lt;/a&gt;&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;02&lt;/td&gt;\r\n&lt;td&gt;\r\n&lt;div class=&quot;skew-1&quot;&gt;2018-2019&lt;/div&gt;\r\n&lt;/td&gt;\r\n&lt;td&gt;&lt;a href=&quot;documents/BE_Almanac_2018-19.pdf&quot; target=&quot;_blank&quot;&gt;&lt;img src=&quot;images/pdf-download.svg&quot; /&gt;&lt;/a&gt;&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;/tbody&gt;\r\n&lt;/table&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;aca-wrapper&quot;&gt;\r\n&lt;h3&gt;2021-2022&lt;/h3&gt;\r\n&lt;h4&gt;All Branches of B.E - II Semester (AICTE)&lt;/h4&gt;\r\n&lt;div class=&quot;table-2&quot;&gt;\r\n&lt;table&gt;\r\n&lt;thead&gt;\r\n&lt;tr&gt;\r\n&lt;th&gt;S.No&lt;/th&gt;\r\n&lt;th&gt;Particulars&lt;/th&gt;\r\n&lt;th&gt;Dates&lt;/th&gt;\r\n&lt;/tr&gt;\r\n&lt;/thead&gt;\r\n&lt;tbody&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;01&lt;/td&gt;\r\n&lt;td&