INSERT INTO `tbl_mjcet_first_submenu` (`menuId`, `menuType`, `menuSulg`, `menuName`, `menuTitle`, `menuDocument`, `menuOrder`, `menuContent`, `menuContentTwo`, `menuImage`, `status`, `addOn`) VALUES
(13, '5', 'admissions', 'Admissions', 'Admissions', '', 3, '&lt;div class=&quot;tabset&quot;&gt;&lt;!-- Tab 1 --&gt; &lt;input id=&quot;tab1&quot; checked=&quot;checked&quot; name=&quot;tabset&quot; type=&quot;radio&quot; /&gt; &lt;label for=&quot;tab1&quot;&gt;Admission into B.E. through EAMCET&lt;/label&gt; &lt;!-- Tab 2 --&gt; &lt;input id=&quot;tab2&quot; name=&quot;tabset&quot; type=&quot;radio&quot; /&gt; &lt;label for=&quot;tab2&quot;&gt;Admission into B.E. through ECET&lt;/label&gt; &lt;input id=&quot;tab3&quot; name=&quot;tabset&quot; type=&quot;radio&quot; /&gt; &lt;label for=&quot;tab3&quot;&gt;Admission into M.E/M.Tech. through GATE/PGECET&lt;/label&gt; &lt;!-- Tab 3 --&gt;\r\n&lt;div class=&quot;tab-panels&quot;&gt;\r\n&lt;section id=&quot;marzen&quot; class=&quot;tab-panel&quot;&gt;\r\n&lt;div class=&quot;aca-wrapper aca-wrapper-1&quot;&gt;\r\n&lt;h4&gt;Eligibility criteria for seeking admission into B.E. (All Courses)&lt;/h4&gt;\r\n&lt;div class=&quot;table-2&quot;&gt;\r\n&lt;table&gt;\r\n&lt;tbody&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;1. The candidate must possess a minimum qualification 10 + 2 (Intermediate ) with Mathematics ,Physics and Chemistry (MPC) as optional subjects&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;2. Candidates belonging to OC and BC must have secured 50% aggregate in 10 + 2 (Intermediate ) level and 45% in optional subjects(MPC)&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;3. Candidates belonging to Reserved Category, Schedule Caste and Schedule Tribe must have secured 45% aggregate and 40% in optional subjects (MPC).&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;4. Candidate should also have qualified in Engineering and Medical Common Entrance Test (EAMCET) conducted by Government of Telangana.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;5. The candidate must fulfill the criteria of Local /Non-local as per the Presidential order of 1963. To be recognized as local, the candidate must have studied for four Consecutive years in the state of Telangana from the Preceding academic year.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;/tbody&gt;\r\n&lt;/table&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;aca-wrapper&quot;&gt;\r\n&lt;h4&gt;Fee particulars:&lt;/h4&gt;\r\n&lt;div class=&quot;table-2&quot;&gt;\r\n&lt;table&gt;\r\n&lt;tbody&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;1. Tuition fee per annum: 1,10,000/-&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;2. The other fee, as approved by the College and Osmania University for the respective academic year will be collected at the time of admission.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;/tbody&gt;\r\n&lt;/table&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;aca-wrapper&quot;&gt;\r\n&lt;h4&gt;Criteria of Allotment of seats :&lt;/h4&gt;\r\n&lt;div class=&quot;table-2&quot;&gt;\r\n&lt;table&gt;\r\n&lt;tbody&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;1. Category-A seats (70%) are allotted by the Convener EAMCET, Government of Telangana through Single window -1&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;2. Category-B seats (30%) are allotted by the college Management under management quota as per rules and regulations laid down by the government of Telangana.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;/tbody&gt;\r\n&lt;/table&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;aca-wrapper&quot;&gt;\r\n&lt;h4&gt;Recognition of College :&lt;/h4&gt;\r\n&lt;div class=&quot;table-2&quot;&gt;\r\n&lt;table&gt;\r\n&lt;tbody&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;1. All the above courses are approved by the Osmania University, Government of Telangana , All India Council Of Technical Education (AICTE ), New Delhi.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;2. 100% of Category-A seats are reserved for Muslim minority Community as the college obtained the minority status from the government of Telangana.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;/tbody&gt;\r\n&lt;/table&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;aca-wrapper&quot;&gt;\r\n&lt;h4&gt;Number of seats sanctioned by Osmania University - Branch wise&lt;/h4&gt;\r\n&lt;div class=&quot;table-2&quot;&gt;\r\n&lt;table&gt;\r\n&lt;thead&gt;\r\n&lt;tr&gt;\r\n&lt;th&gt;S.No&lt;/th&gt;\r\n&lt;th&gt;Course&lt;/th&gt;\r\n&lt;th&gt;Convener quota&lt;/th&gt;\r\n&lt;th&gt;Management quota&lt;/th&gt;\r\n&lt;th&gt;Total seats&lt;/th&gt;\r\n&lt;/tr&gt;\r\n&lt;/thead&gt;\r\n&lt;tbody&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;01&lt;/td&gt;\r\n&lt;td&gt;Artificial Intelligence &amp;amp; Data Science&lt;/td&gt;\r\n&lt;td&gt;84&lt;/td&gt;\r\n&lt;td&gt;36&lt;/td&gt;\r\n&lt;td&gt;120&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;02&lt;/td&gt;\r\n&lt;td&gt;Artificial Intelligence &amp;amp; Machine Learning&lt;/td&gt;\r\n&lt;td&gt;42&lt;/td&gt;\r\n&lt;td&gt;18&lt;/td&gt;\r\n&lt;td&gt;60&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;03&lt;/td&gt;\r\n&lt;td&gt;Civil Engineering&lt;/td&gt;\r\n&lt;td&gt;42&lt;/td&gt;\r\n&lt;td&gt;18&lt;/td&gt;\r\n&lt;td&gt;60&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;04&lt;/td&gt;\r\n&lt;td&gt;Computer Science Engineering&lt;/td&gt;\r\n&lt;td&gt;126&lt;/td&gt;\r\n&lt;td&gt;54&lt;/td&gt;\r\n&lt;td&gt;180&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;05&lt;/td&gt;\r\n&lt;td&gt;Electrical and Electronics Engineering&lt;/td&gt;\r\n&lt;td&gt;42&lt;/td&gt;\r\n&lt;td&gt;18&lt;/td&gt;\r\n&lt;td&gt;60&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;06&lt;/td&gt;\r\n&lt;td&gt;Electronics and Communication Engineering&lt;/td&gt;\r\n&lt;td&gt;84&lt;/td&gt;\r\n&lt;td&gt;36&lt;/td&gt;\r\n&lt;td&gt;120&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;07&lt;/td&gt;\r\n&lt;td&gt;Mechanical Engineering&lt;/td&gt;\r\n&lt;td&gt;42&lt;/td&gt;\r\n&lt;td&gt;18&lt;/td&gt;\r\n&lt;td&gt;60&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;08&lt;/td&gt;\r\n&lt;td&gt;Information Technology&lt;/td&gt;\r\n&lt;td&gt;84&lt;/td&gt;\r\n&lt;td&gt;36&lt;/td&gt;\r\n&lt;td&gt;120&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;Total&lt;/td&gt;\r\n&lt;td&gt;&amp;nbsp;&lt;/td&gt;\r\n&lt;td&gt;546&lt;/td&gt;\r\n&lt;td&gt;234&lt;/td&gt;\r\n&lt;td&gt;780&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;/tbody&gt;\r\n&lt;/table&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/section&gt;\r\n&lt;section id=&quot;rauchbier&quot; class=&quot;tab-panel&quot;&gt;\r\n&lt;div class=&quot;aca-wrapper aca-wrapper-1&quot;&gt;\r\n&lt;h4&gt;Eligibility Criteria for seeking admission into B.E. through Lateral Entry (ECET)&lt;/h4&gt;\r\n&lt;div class=&quot;table-2&quot;&gt;\r\n&lt;table&gt;\r\n&lt;tbody&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;1. The candidate must possess a minimum qualification of 10 + 3 (Three years in polytechnic diploma course with relevant group).&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;2. Candidates belonging to OC and BC must have secured 50% aggregate.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;3. Candidates belonging to Reserved Category (Schedule Caste and Schedule Tribe) must have secured 45% aggregate&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;4. Candidate should also have qualified in Engineering Common Entrance Test (ECET) conducted by the Government of Telangana.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;5. The candidate must fulfill the criteria of Local /Non-local as per the Presidential order of 1963. To be recognized as local, the candidate must have studied for five consecutive years in the state of Telangana from the Preceding academic year.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;/tbody&gt;\r\n&lt;/table&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;aca-wrapper&quot;&gt;\r\n&lt;h4&gt;Fee particulars:&lt;/h4&gt;\r\n&lt;div class=&quot;table-2&quot;&gt;\r\n&lt;table&gt;\r\n&lt;tbody&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;1. Tuition fee per annum: 1,10,000/-&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;2. The other fee, as approved by the College and Osmania University for the respective academic year will be collected at the time of admission.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;/tbody&gt;\r\n&lt;/table&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;aca-wrapper&quot;&gt;\r\n&lt;h4&gt;Criteria of Allotment of seats :&lt;/h4&gt;\r\n&lt;div class=&quot;table-2&quot;&gt;\r\n&lt;table&gt;\r\n&lt;tbody&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;1. All the seats are allotted by the Convener ECET, Government of Telangana through Single window -1.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;2. There is no management quota for lateral entry admissions.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;/tbody&gt;\r\n&lt;/table&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;aca-wrapper&quot;&gt;\r\n&lt;h4&gt;Recognition of College :&lt;/h4&gt;\r\n&lt;div class=&quot;table-2&quot;&gt;\r\n&lt;table&gt;\r\n&lt;tbody&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;1. All the below listed courses are approved by the Osmania University, Government of Telangana , All India Council Of Technical Education (AICTE ), New Delhi.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;2. 100% of the seats are reserved for Muslim minority Community as the college obtained the minority status from the government of Telangana.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;/tbody&gt;\r\n&lt;/table&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;aca-wrapper&quot;&gt;\r\n&lt;h4&gt;Number of seats sanctioned by Osmania University - Branch wise&lt;/h4&gt;\r\n&lt;div class=&quot;table-2&quot;&gt;\r\n&lt;table&gt;\r\n&lt;thead&gt;\r\n&lt;tr&gt;\r\n&lt;th&gt;S.No&lt;/th&gt;\r\n&lt;th&gt;Course&lt;/th&gt;\r\n&lt;th&gt;Sanctioned seats to the college&lt;/th&gt;\r\n&lt;th&gt;Number of seats to be admitted in II year level&lt;/th&gt;\r\n&lt;/tr&gt;\r\n&lt;/thead&gt;\r\n&lt;tbody&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;01&lt;/td&gt;\r\n&lt;td&gt;Artificial Intelligence &amp;amp; Data Science&lt;/td&gt;\r\n&lt;td&gt;60&lt;/td&gt;\r\n&lt;td&gt;06&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;02&lt;/td&gt;\r\n&lt;td&gt;Artificial Intelligence &amp;amp; Machine Learning&lt;/td&gt;\r\n&lt;td&gt;60&lt;/td&gt;\r\n&lt;td&gt;06&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;03&lt;/td&gt;\r\n&lt;td&gt;Civil Engineering&lt;/td&gt;\r\n&lt;td&gt;120&lt;/td&gt;\r\n&lt;td&gt;12&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;04&lt;/td&gt;\r\n&lt;td&gt;Computer Science Engineering&lt;/td&gt;\r\n&lt;td&gt;120&lt;/td&gt;\r\n&lt;td&gt;12&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;05&lt;/td&gt;\r\n&lt;td&gt;Electrical and Electronics Engineering&lt;/td&gt;\r\n&lt;td&gt;60&lt;/td&gt;\r\n&lt;td&gt;06&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;06&lt;/td&gt;\r\n&lt;td&gt;Electronics and Communication Engineering&lt;/td&gt;\r\n&lt;td&gt;120&lt;/td&gt;\r\n&lt;td&gt;12&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;07&lt;/td&gt;\r\n&lt;td&gt;Mechanical Engineering&lt;/td&gt;\r\n&lt;td&gt;120&lt;/td&gt;\r\n&lt;td&gt;12&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;08&lt;/td&gt;\r\n&lt;td&gt;Information Technology&lt;/td&gt;\r\n&lt;td&gt;120&lt;/td&gt;\r\n&lt;td&gt;12&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;Total&lt;/td&gt;\r\n&lt;td&gt;&amp;nbsp;&lt;/td&gt;\r\n&lt;td&gt;780&lt;/td&gt;\r\n&lt;td&gt;78&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;/tbody&gt;\r\n&lt;/table&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/section&gt;\r\n&lt;section id=&quot;mjcet&quot; class=&quot;tab-panel&quot;&gt;\r\n&lt;div class=&quot;aca-wrapper aca-wrapper-1&quot;&gt;\r\n&lt;h4&gt;Eligibility Criteria for seeking admission into M.E/M.Tech. (All Courses)&lt;/h4&gt;\r\n&lt;div class=&quot;table-2&quot;&gt;\r\n&lt;table&gt;\r\n&lt;tbody&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;1. A Bachelor&amp;rsquo;s degree in Engineering/Technology of Osmania University.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;2. AMIE Degree or similar qualification recognized by the UPSC as equivalent to B.E./B.Tech.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;3. Any other qualification which is recognized as equivalent to the Bachelor&amp;rsquo;s Degree in Engineering/Technology of Osmania University.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;4. For M.Tech. (Computer Science and Engineering), Master&amp;rsquo;s Degree holders in Physics, Statistics, Mathematics, or Applied Mathematics, Applied Statistics, Applied Physics, Geophysics and Computer Applications are also eligible. However, all candidates should have valid GATE score in CSE / IT only or any other entrance test conducted by the competent authority.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;5. For M.E. (Civil) programme with specialization in Construction Engineering and Management, candidates with B.Arch. Degree are also eligible.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;6. For M.E. (BME) programme with specialization in Bio-Medical Electronics, candidates with B.E. Degree in Bio Medical Engg. / Electrical and Electronics Engg. / Electronics &amp;amp; Communication Engg. / Instrumentation Engg. or its equivalent are eligible.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;7. For M.E. (EE) programme with specialization in Power Electronics &amp;amp; Systems, candidates with B.E./B.Tech in Instrumentation / Electrical Engineering / Electrical and Electronics Engineering / Electronics and Instrumentation Engineering are eligible.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;8. The candidates will be admitted strictly in accordance with the merit secured at the Entrance Examination conducted by the Government of Telangana, keeping in view the rules in force regarding the reservations of seats to various categories of candidates.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;/tbody&gt;\r\n&lt;/table&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;aca-wrapper&quot;&gt;\r\n&lt;h4&gt;Fee particulars:&lt;/h4&gt;\r\n&lt;div class=&quot;table-2&quot;&gt;\r\n&lt;table&gt;\r\n&lt;tbody&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;1. Tuition fee per annum: 1,10,000/-&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;2. The other fee, as approved by the College and Osmania University for the respective academic year will be collected at the time of admission.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;/tbody&gt;\r\n&lt;/table&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;aca-wrapper&quot;&gt;\r\n&lt;h4&gt;Criteria of Allotment of seats :&lt;/h4&gt;\r\n&lt;div class=&quot;table-2&quot;&gt;\r\n&lt;table&gt;\r\n&lt;tbody&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;1. Category-A seats (70%) are allotted by the Convener PGECET, Government of Telangana through Single window -1.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;2. Category-B seats (30%) are allotted by the college Management under management quota as per rules and regulations laid down by the government of Telangana.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;/tbody&gt;\r\n&lt;/table&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;aca-wrapper&quot;&gt;\r\n&lt;h4&gt;Recognition of College :&lt;/h4&gt;\r\n&lt;div class=&quot;table-2&quot;&gt;\r\n&lt;table&gt;\r\n&lt;tbody&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;1. All the below listed courses are approved by the Osmania University, Government of Telangana , All India Council Of Technical Education (AICTE ), New Delhi.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;2. 100% of Category-A seats are reserved for Muslim minority Community as the college obtained the minority status from the government of Telangana.&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;/tbody&gt;\r\n&lt;/table&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;div class=&quot;aca-wrapper&quot;&gt;\r\n&lt;h4&gt;Number of seats sanctioned by Osmania University - Branch wise&lt;/h4&gt;\r\n&lt;div class=&quot;table-2&quot;&gt;\r\n&lt;table&gt;\r\n&lt;thead&gt;\r\n&lt;tr&gt;\r\n&lt;th&gt;S.No&lt;/th&gt;\r\n&lt;th&gt;Course&lt;/th&gt;\r\n&lt;th&gt;Convener quota&lt;/th&gt;\r\n&lt;th&gt;Management quota&lt;/th&gt;\r\n&lt;th&gt;Total seats&lt;/th&gt;\r\n&lt;/tr&gt;\r\n&lt;/thead&gt;\r\n&lt;tbody&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;01&lt;/td&gt;\r\n&lt;td&gt;CAD/CAM&lt;/td&gt;\r\n&lt;td&gt;12/13&lt;/td&gt;\r\n&lt;td&gt;06/05&lt;/td&gt;\r\n&lt;td&gt;18&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;02&lt;/td&gt;\r\n&lt;td&gt;CSE&lt;/td&gt;\r\n&lt;td&gt;17/18&lt;/td&gt;\r\n&lt;td&gt;07/06&lt;/td&gt;\r\n&lt;td&gt;24&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;03&lt;/td&gt;\r\n&lt;td&gt;Digital Systems&lt;/td&gt;\r\n&lt;td&gt;17/18&lt;/td&gt;\r\n&lt;td&gt;07/06&lt;/td&gt;\r\n&lt;td&gt;24&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;04&lt;/td&gt;\r\n&lt;td&gt;Power Electronic Systems&lt;/td&gt;\r\n&lt;td&gt;12/13&lt;/td&gt;\r\n&lt;td&gt;06/05&lt;/td&gt;\r\n&lt;td&gt;18&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;05&lt;/td&gt;\r\n&lt;td&gt;Strucutral Engineering&lt;/td&gt;\r\n&lt;td&gt;12/13&lt;/td&gt;\r\n&lt;td&gt;06/05&lt;/td&gt;\r\n&lt;td&gt;18&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;Total&lt;/td&gt;\r\n&lt;td&gt;&amp;nbsp;&lt;/td&gt;\r\n&lt;td&gt;70/75&lt;/td&gt;\r\n&lt;td&gt;32/27&lt;/td&gt;\r\n&lt;td&gt;102&lt;/td&gt;\r\n&lt;/tr&gt;\r\n&lt;/tbody&gt;\r\n&lt;/table&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;\r\n&lt;/section&gt;\r\n&lt;/div&gt;\r\n&lt;/div&gt;', '', '', '1', '2023-01-03 21:10:43'),
(14, '5', 'university-ranks', 'University Ranks', 'University Ranks', '', 4, '&lt;h4&gt;&lt;a href=&quot;documents/university-list.pdf&quot; target=&quot;_blank&quot;&gt;Click here to view University Ranks from 2004-2019&lt;/a&gt;&lt;/h4&gt;\r\n&lt;!--&lt;h4&gt;Select the year from the list to display University Ranks year wise&lt;/h4&gt;\r\n&lt;div class=&quot;university-list&quot;&gt;\r\n	&lt;select&gt;\r\n		&lt;option&gt;Select Year&lt;/option&gt;\r\n		&lt;option&gt;2022&lt;/option&gt;\r\n		&lt;option&gt;2021&lt;/option&gt;\r\n		&lt;option&gt;2020&lt;/option&gt;\r\n	&lt;/select&gt;\r\n	&lt;input type=&quot;submit&quot; value=&quot;Submit&quot; class=&quot;submit&quot;&gt;\r\n&lt;/div&gt;--&gt;\r\n&lt;h4&gt;University Ranks Obtained in the Last Ten Years:&lt;/h4&gt;\r\n&lt;p&gt;MJCET is best known for its commitment to facilitate the best Engineering education to its students who would be technically conversant to cope with multifarious professional challenges. The 100% pass performance of our students in the Master Degree programme reflected in the university results attest the fact that MJCET is indeed an institute of Academic Excellence.&lt;/p&gt;\r\n&lt;div class=&quot;table-2&quot;&gt;\r\n&lt;table&gt;\r\n&lt;thead&gt;\r\n&lt;tr&gt;\r\n&lt;th style=&quot;width: 100px;&quot;&gt;Department&lt;/th&gt;\r\n&lt;th&gt;2010&lt;/th&gt;\r\n&lt;th&gt;2011&lt;/th&gt;\r\n&lt;th&gt;2012&lt;/th&gt;\r\n&lt;th&gt;2013&lt;/th&gt;\r\n&lt;th&gt;2014&lt;/th&gt;\r\n&lt;th&gt;2015&lt;/th&gt;\r\n&lt;th&gt;2016&lt;/th&gt;\r\n&lt;th&gt;2017&lt;/th&gt;\r\n&lt;th&gt;2018&lt;/th&gt;\r\n&lt;th&gt;2019&lt;/th&gt;\r\n&lt;th&gt;2020&lt;/th&gt;\r\n&lt;th&gt;2021&lt;/th&gt;\r\n&lt;/tr&gt;\r\n&lt;/thead&gt;\r\n&lt;tbody&gt;\r\n&lt;tr&gt;\r\n&lt;td&gt;&lt;strong&gt;Civil Engineering&lt;/strong&gt;&lt;/td&gt;\r\n&lt;td&gt;4&lt;/td&gt;\r\n&lt;td&gt;1,2&lt;/td&gt;\r\n&lt;td&gt;-&lt;/td&gt;\r\n&lt;td&gt;7&lt;/td&gt;\r\n&lt;td&gt;2, 4, 7&lt;/td&gt;\r\n&lt;td&gt;7, 9, 10&lt;/td&gt;\r\n&lt;td&gt;1&lt;/