INSERT INTO `tbl_pages` (`pageId`, `pageHeading`, `pageMenuId`, `pageImage`, `pageContent`, `txtMenuContentShort`, `status`, `tagline`, `order`, `addOn`) VALUES
(2, 'Year End Programs', 4, 'Year-End-Programs.png', '&lt;p&gt;As a part of Year End programs students will have a iterative journey with electronics and coding, which will give them a deep knowledge of each robot/ project is made with respect to the requirement. Through the process they come across extensive maths and science principles or theories applied in a more practical way with the program they are enrolled in which will ensure academic performance as well.&lt;/p&gt;\r\n&lt;div class=&quot;clear-fix&quot;&gt;&amp;nbsp;&lt;/div&gt;\r\n&lt;h4&gt;What a school / Student will Receive from Edueme&lt;/h4&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Comprehensive Curriculum&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Kits &amp;amp; Software&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Books / E material&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;In - Class sessions&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Assessments&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Certifications&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Tech Summits&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Expo\'s ( Pradarshan)&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Inter/ Intra School Competitions&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Tech Tours (Anveshana)&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Support in all the business days/hours.&lt;/li&gt;\r\n&lt;/ul&gt;', '&lt;p&gt;As a part of Year End programs students will have a iterative journey with electronics and coding, which will give them a deep knowledge of each robot/ project is made with respect to the requirement.&lt;/p&gt;', '1', 'Duration : 10 Months', '1', '2023-03-28 08:09:27'),
(3, 'Workshop 1', 6, 'Year-End-Programs.png', '&lt;p&gt;The main agenda of any workshop is to introduce a new skill or tech to the students and make them fascinated, drive them towards having a long journey in prospering the skill. In this short journey students will get introduced to may electronic component and way to comand them with basic coding skills. This introduction will help them to explore their creative thoughts.&lt;/p&gt;\r\n&lt;div class=&quot;clear-fix&quot;&gt;&amp;nbsp;&lt;/div&gt;\r\n&lt;h4&gt;What a school / Student will Receive from Edueme&lt;/h4&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Comprehensive Curriculum&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Kits &amp;amp; Software&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;E material&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;In - Class sessions&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Certifications&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Tech Summits&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Expo\'s ( Pradarshan)&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Intra School Competitions&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Support in all the business days/hours.&lt;/li&gt;\r\n&lt;/ul&gt;', '&lt;p&gt;The main agenda of any workshop is to introduce a new skill or tech to the students and make them fascinated, drive them towards having a long journey in prospering the skill. In this short journey students will get introduced to may electronic component and way to comand them with basic coding skills. This introduction will help them to explore their creative thoughts.&lt;/p&gt;', '1', 'Duration : 15 Days Programm, Venue: Phoenix Greens School of Learning, Kokapet, Hyderabad. TS', '1', '2023-03-28 08:10:55'),
(4, 'Awesome Teachers:', 8, 'awesome-teachers-icon.png', '', '&lt;p&gt;Having exceptional teachers is crucial to providing cutting-edge robotics education, and this is what our team of expert instructors brings to the table.&lt;/p&gt;', '1', '', '1', '2023-04-12 16:21:01'),
(5, 'Best Programme', 8, 'best-programme-icon.png', '', '&lt;p&gt;Robotics education is divided into two separate tracks: robotics with electronics and robotics with artificial intelligence.&lt;/p&gt;', '1', '', '2', '2023-04-12 16:29:59'),
(6, 'Global Certificate', 8, 'global-certificate-icon.png', '', '&lt;p&gt;Students gain a thorough understanding of the newest technology and industry best practises through our widely renowned certification programme in robotics and artificial intelligence&lt;/p&gt;', '1', '', '3', '2023-04-12 16:30:44'),
(7, 'Business Knowledge', 8, 'business-knowledge-icon.png', '', '&lt;p&gt;We can emphasize that our robotics education services provide children with a unique opportunity to gain hands-on knowledge by learning about the latest technologies..&lt;/p&gt;', '1', '', '4', '2023-04-12 16:31:30'),
(8, 'How Edueme Prayogshala looks like', 14, 'blog-thumb-1a.png', '', '', '1', 'Starts on 25 April 2023', '1', '2023-04-12 20:38:21'),
(9, 'How Artificial Intelligence helps changing our daily lives?', 14, 'blog-thumb-1b.png', '', '', '1', 'Starts on 18 march 2023', '2', '2023-04-12 20:38:21'),
(10, 'How Edueme helps building Young generations towards greater Innovators?', 14, 'ai.png', '', '', '1', 'Starts on 02 April 2023', '3', '2023-04-12 20:40:06'),
(11, 'Workshops 2', 6, 'Boot-Camps.png', '&lt;h5&gt;Name of the Event: Summer Camp &amp;ndash; Robotics Workshop&lt;/h5&gt;\r\n&lt;p&gt;The main agenda of any workshop is to introduce a new skill or tech to the students and make them fascinated, drive them towards having a long journey in prospering the skill. In this short journey students will get introduced to may electronic component and way to comand them with basic coding skills. This introduction will help them to explore their creative thoughts.&lt;/p&gt;\r\n&lt;div class=&quot;clear-fix&quot;&gt;&amp;nbsp;&lt;/div&gt;\r\n&lt;h4&gt;What a school / Student will Receive from Edueme&lt;/h4&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Comprehensive Curriculum&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Kits &amp;amp; Software&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;E material&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;In - Class sessions&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Certifications&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Tech Summits&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Expo\'s ( Pradarshan)&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Intra School Competitions&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Support in all the business days/hours.&lt;/li&gt;\r\n&lt;/ul&gt;', '&lt;p&gt;The main agenda of any workshop is to introduce a new skill or tech to the students and make them fascinated, drive them towards having a long journey in prospering the skill. In this short journey students will get introduced to may electronic component and way to comand them with basic coding skills. This introduction will help them to explore their creative thoughts.&lt;/p&gt;', '1', 'Duration : 15 Days Programm, Venue: Arka international School, Almasguda, BN Reddy, Hyderabad. TS', '2', '2023-04-13 06:33:45'),
(12, 'Workshops 3', 6, 'Workshops.png', '&lt;h4&gt;Name of the Event: Summer Camp &amp;ndash; Robotics Workshop&lt;/h4&gt;\r\n&lt;p&gt;The main agenda of any workshop is to introduce a new skill or tech to the students and make them fascinated, drive them towards having a long journey in prospering the skill. In this short journey students will get introduced to may electronic component and way to comand them with basic coding skills. This introduction will help them to explore their creative thoughts.&lt;/p&gt;\r\n&lt;div class=&quot;clear-fix&quot;&gt;&amp;nbsp;&lt;/div&gt;\r\n&lt;h4&gt;What a school / Student will Receive from Edueme&lt;/h4&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Comprehensive Curriculum&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Kits &amp;amp; Software&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;E material&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;In - Class sessions&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Certifications&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Tech Summits&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Expo\'s ( Pradarshan)&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Intra School Competitions&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Support in all the business days/hours.&lt;/li&gt;\r\n&lt;/ul&gt;', '&lt;p&gt;The main agenda of any workshop is to introduce a new skill or tech to the students and make them fascinated, drive them towards having a long journey in prospering the skill. In this short journey students will get introduced to may electronic component and way to comand them with basic coding skills. This introduction will help them to explore their creative thoughts.&lt;/p&gt;', '1', 'Duration : 15 Days Programm, &lt;br&gt;Venue: Contact US for more Details on +91 9059508050', '3', '2023-04-13 06:34:25'),
(13, 'Boot Camps', 4, 'Boot-Camps.png', '&lt;p&gt;As a part of boot camps Students will have a short journey for a term or a semester learning all the required basics of the electronics and coding enough to start making their own creative stuff. In this journey students will start socializing themselves as the best way to learn more in less time is to team up with the peers. This way they enjoy the learning process.&lt;/p&gt;\r\n&lt;div class=&quot;clear-fix&quot;&gt;&amp;nbsp;&lt;/div&gt;\r\n&lt;h4&gt;What a school / Student will Receive from Edueme&lt;/h4&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Comprehensive Curriculum&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Kits &amp;amp; Software&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;E material&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;In - Class sessions&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Assessments&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Certifications&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Tech Summits&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Expo\'s ( Pradarshan)&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Intra School&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Competitions&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Support in all the business days/hours.&lt;/li&gt;\r\n&lt;/ul&gt;', '&lt;p&gt;As a part of boot camps Students will have a short journey for a term or a semester learning all the required basics of the electronics and coding enough to start making their own creative stuff&amp;hellip;&lt;/p&gt;', '1', 'Duration : 4 weeks - 12 weeks (2 days a week)', '2', '2023-04-13 06:51:33'),
(14, 'Workshops', 4, 'Workshops.png', '&lt;p&gt;The main agenda of any workshop is to introduce a new skill or tech to the students and make them fascinated, drive them towards having a long journey in prospering the skill. In this short journey students will get introduced to may electronic component and way to comand them with basic coding skills. This introduction will help them to explore their creative thoughts.&lt;/p&gt;\r\n&lt;div class=&quot;clear-fix&quot;&gt;&amp;nbsp;&lt;/div&gt;\r\n&lt;h4&gt;What a school / Student will Receive from Edueme&lt;/h4&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Comprehensive Curriculum&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Kits &amp;amp; Software&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;E material&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;In - Class sessions&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Assessments&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Certifications&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Tech Summits&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Expo\'s ( Pradarshan)&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Intra School Competitions&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Support in all the business days/hours.&lt;/li&gt;\r\n&lt;/ul&gt;', '&lt;p&gt;The main agenda of any workshop is to introduce a new skill or tech to the students and make them fascinated, drive them towards having a long journey in prospering the skill. In this short journey students will get&amp;hellip;&lt;/p&gt;', '1', 'Duration : 1 week - 2 weeks ( 2 days a week)', '3', '2023-04-13 06:52:55'),
(15, 'Teacher Training Programs', 4, 'Teacher-Training-Programs.png', '&lt;p&gt;As a part of this program one or two teachers from the school will be trained prior to the academic year. These trained teachers will be teaching the students for the whole academic year for the enrolled program.&lt;/p&gt;\r\n&lt;div class=&quot;clear-fix&quot;&gt;&amp;nbsp;&lt;/div&gt;\r\n&lt;h4&gt;What a school / Student will Receive from Edueme&lt;/h4&gt;\r\n&lt;ul&gt;\r\n&lt;li&gt;Tech teaching methods&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Creating Comprehensive curriculum&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Designing innovative projects&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Creating a Maker Space&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Creating Assessments / Activities&lt;/li&gt;\r\n&amp;nbsp;\r\n&lt;li&gt;Progress Analysis &amp;amp; measures&lt;/li&gt;\r\n&lt;/ul&gt;', '&lt;p&gt;As a part of this program one or two teachers from the school will be trained prior to the academic year. These trained teachers will be teaching the students for the whole academic year for the enrolled program...&lt;/p&gt;', '1', 'Duration : 8 weeks - 14 weeks ( 1- 1.5 hours each business day )', '4', '2023-04-13 06:53:59'),
(16, 'Tech Labs (Prayogashala)', 4, 'Tech-Labs.png', '&lt;p&gt;We also custom design and setup industry grade tech labs where students can learn and start being creative with the skills they gain in the class room. This lab will be equipped with each and every hard- ware component starting from screws to advanced micro controllers and sensors needed in students journey of learning, we also provide aesthetic materials like colours, foam sheets etc. in order to encourage students to bring attractive looks to their creative stuff.&lt;/p&gt;', '&lt;p&gt;We also custom design and setup industry grade tech labs where students can learn and start being creative with the skills they gain in the class room. This lab will be equipped with each and every hardware&amp;hellip;&lt;/p&gt;', '1', '', '5', '2023-04-13 06:54:53'),
(17, 'Tech Summits', 4, 'Tech-Summits.png', '&lt;p&gt;There will be one Tech Summit where professionals working in MNC companies on cutting edge tech- nologies will spend their time with students on the proposed date. This will be a great fun as students will be able to ask and discuss with the professionals about the advancement of technology as well as their doubts if any. This discussions will also help students in choosing their career or get guidance to plan their journey towards future opportunities.&lt;/p&gt;', '&lt;p&gt;professionals working in MNC companies on cutting edge technologies will spend their time with students on the proposed date. This will be a great fun as students&amp;hellip;&lt;/p&gt;', '1', '', '6', '2023-04-13 06:55:31'),
(18, 'Expoâ€™s (Pradarshan)', 4, 'Expos-Pradarshan.png', '&lt;p&gt;This Expo\'s gives students a chance to present their skills. This will also help them socialize, learn to work in teams, build confidence and presentational skills. This also helps them to understand various types of other things developed by other students which can be out of their perception and thought process. This event also helps in diversifying their thought process in early ages.&lt;/p&gt;', '&lt;p&gt;This Expo&amp;rsquo;s gives students a chance to present their skills. This will also help them socialize, learn to work in teams, build confidence and presentational skills. This also helps them to understand&amp;hellip;&lt;/p&gt;', '1', '', '7', '2023-04-13 06:56:15'),
(19, 'Inter/Intra school Competitions', 4, 'Inter-Intra-school-ompetitions.png', '&lt;p&gt;This Competitions helps children to drive themselves in a fast paced competitive environment as they will create things matching the given problem statement with in the time given. There will be a lot of fun activities arranged as part of these competitions not limited to Making different Robots/ Projects, Tech Quiz etc. This will help students in understanding the position about where they stand and also figure out the way to progress further.&lt;/p&gt;', '&lt;p&gt;This Competitions helps children to drive themselves in a fast paced competitive environment as they will create things matching the given problem statement with in the time given&amp;hellip;&lt;/p&gt;', '1', '', '8', '2023-04-13 06:56:52'),
(20, 'Tech Tours (Anveshana)', 4, 'Tech-Tours-Anveshana.png', '&lt;p&gt;Anveshana is a structured tech tour mainly focuses on helping the students to wider their knowledge of building industry standard things. we plan these tours National level institutions and Universities mainly to IIT\'s, NIT\'s and top universities in the city, introduce the tech labs, innovative products and other equipment&amp;rsquo;s they use as a part of their learning journey as well as their progress in the current industry. This tour\'s will help students in understanding the importance of planning their journey of learning to national level institutions.&lt;/p&gt;\r\n&lt;p&gt;This will also introduce them to different type of tech and entrepreneur clubs in the institutions which will in turn help them to create such environment in schools progressing their career in very early ages.&lt;/p&gt;', '&lt;p&gt;Anveshana is a structured tech tour mainly focuses on helping the students to wider their knowledge of building industry standard things. we plan these tours National level institutions and Universities mainly to IIT&amp;rsquo;s, NIT&amp;rsquo;s and&amp;hellip;&lt;/p&gt;', '1', '', '9', '2023-04-13 06:57:44');

